// Custom function to calculate distance from a point to a line segment
function distToSegment(px, py, x1, y1, x2, y2) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let lenSq = dx * dx + dy * dy;

  if (lenSq === 0) { // It's a point, not a segment
    return dist(px, py, x1, y1);
  }

  // Calculate t, the projection of the point (px, py) onto the infinite line
  // defined by the segment (x1,y1)-(x2,y2).
  // t is normalized distance along the segment where the projection falls.
  let t = ((px - x1) * dx + (py - y1) * dy) / lenSq;

  // Clamp t to 0-1, so the projected point is guaranteed to be on the segment
  t = constrain(t, 0, 1);

  // Find the closest point on the segment
  let closestX = x1 + t * dx;
  let closestY = y1 + t * dy;

  // Return the distance from the original point to this closest point on the segment
  return dist(px, py, closestX, closestY);
}

